UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
    "Transpose": { 
        "Account": "SELECT attribute, data FROM t17refined.masters.accounts, UNNEST(ARRAY[ROW(''account id'', CAST(iaccountid AS VARCHAR)), ROW(''customer id'', CAST(icustomerid AS VARCHAR)), ROW(''external account id'', vcexternalaccountid), ROW(''bmerchant'', CAST(bmerchant AS VARCHAR)), ROW(''record status'', CAST(irecordstatus AS VARCHAR)), ROW(''entry date time'', CAST(dtentrydatetime AS VARCHAR))]) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY iaccountid DESC LIMIT :Load ",
        "VPA": "SELECT attribute, data FROM t17refined.masters.vpa, UNNEST(ARRAY[ROW(''vpa id'', CAST(ivpaid AS VARCHAR)), ROW(''account id'', CAST(iaccountid AS VARCHAR)), ROW(''external address id'', vcexternaladdressid), ROW(''address'', vcaddress), ROW(''vpaname'', vcvpaname), ROW(''MCC'', CAST(imcc AS VARCHAR)), ROW(''bmerchant'', CAST(bmerchant AS VARCHAR)), ROW(''entry date time'', CAST(dtentrydatetime AS VARCHAR)), ROW(''irecordstatus'', CAST(irecordstatus AS VARCHAR))]) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY ivpaid DESC LIMIT :Load ",
        "Customer": "SELECT attribute, data FROM t17refined.masters.customers, UNNEST(ARRAY[ROW(''Customer ID'', CAST(icustomerid AS VARCHAR)), ROW(''External Cust ID'', vcexternalcustid), ROW(''Customer Name'', vccustomername), ROW(''Onboarded On'', CAST(dtonboardingdate AS VARCHAR)), ROW(''MCC'', CAST(imcc AS VARCHAR)), ROW(''PAN'', json_extract_scalar(vcattribs, ''$.pan'')), ROW(''City'', json_extract_scalar(vcattribs, ''$.city'')), ROW(''GSTN'', json_extract_scalar(vcattribs, ''$.gstn'')), ROW(''LLPIN'', json_extract_scalar(vcattribs, ''$.llpin'')), ROW(''State'', json_extract_scalar(vcattribs, ''$.state'')), ROW(''Status'', json_extract_scalar(vcattribs, ''$.status'')), ROW(''Country'', json_extract_scalar(vcattribs, ''$.country'')), ROW(''Pincode'', json_extract_scalar(vcattribs, ''$.pincode'')), ROW(''District'', json_extract_scalar(vcattribs, ''$.district'')), ROW(''Latitude'', json_extract_scalar(vcattribs, ''$.latitude'')), ROW(''Longitude'', json_extract_scalar(vcattribs, ''$.longitude'')), ROW(''Partner Name'', json_extract_scalar(vcattribs, ''$.partnerName'')), ROW(''Business Name'', json_extract_scalar(vcattribs, ''$.businessName'')), ROW(''Merchant Type'', json_extract_scalar(vcattribs, ''$.merchantType'')), ROW(''Registered mobile'', vcregisteredmobile), ROW(''Turnover Type'', json_extract_scalar(vcattribs, ''$.turnoverType'')), ROW(''Ownership Type'', json_extract_scalar(vcattribs, ''$.ownershipType'')), ROW(''Acceptance Type'', json_extract_scalar(vcattribs, ''$.acceptanceType'')), ROW(''Verified AccountName'', json_extract_scalar(vcattribs, ''$.sellerVerifiedAccountName'')), ROW(''Settlement Account No'', json_extract_scalar(vcattribs, ''$.settlementAccountNo'')), ROW(''Settlement IFSC Code'', json_extract_scalar(vcattribs, ''$.settlementIfscCode'')), ROW(''OCL Onboarding Date'', json_extract_scalar(vcattribs, ''$.oclOnboardingDate'')), ROW(''record status'', CAST(irecordstatus AS VARCHAR))]) AS t(attribute, data) WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY icustomerid DESC LIMIT :Load "
    },
    "Normal": {
        "Account": "SELECT iaccountid AS \\"Account ID\\", icustomerid AS \\"Customer ID\\", vcexternalaccountid AS \\"External Account ID\\", bmerchant AS \\"Merchant\\", irecordstatus AS \\"Record Status\\", dtentrydatetime AS \\"Entry Date Time\\" FROM t17refined.masters.accounts WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY iaccountid DESC LIMIT :Load ",
        "VPA": "SELECT ivpaid AS \\"VPA ID\\", iaccountid AS \\"Account ID\\", vcexternaladdressid AS \\"External Address ID\\", vcaddress AS \\"Payment Address\\", vcvpaname AS \\"VPA Name\\", imcc AS \\"MCC\\", bmerchant AS \\"Merchant\\", dtentrydatetime AS \\"Entry Date Time\\", irecordstatus AS \\"Record Status\\" FROM t17refined.masters.vpa WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY ivpaid DESC LIMIT :Load ",
        "Customer": "SELECT icustomerid AS \\"Customer ID\\", vcexternalcustid AS \\"External Cust ID\\", vccustomername AS \\"Customer Name\\", dtonboardingdate AS \\"Onboarded On\\", imcc AS \\"MCC\\", json_extract_scalar(vcattribs, ''$.pan'') AS \\"PAN\\", json_extract_scalar(vcattribs, ''$.city'') AS \\"City\\", json_extract_scalar(vcattribs, ''$.gstn'') AS \\"GSTN\\", json_extract_scalar(vcattribs, ''$.llpin'') AS \\"LLPIN\\", json_extract_scalar(vcattribs, ''$.state'') AS \\"State\\", json_extract_scalar(vcattribs, ''$.status'') AS \\"Status\\", json_extract_scalar(vcattribs, ''$.country'') AS \\"Country\\", json_extract_scalar(vcattribs, ''$.pincode'') AS \\"Pin Code\\", json_extract_scalar(vcattribs, ''$.district'') AS \\"District\\", json_extract_scalar(vcattribs, ''$.latitude'') AS \\"Latitude\\", json_extract_scalar(vcattribs, ''$.longitude'') AS \\"Longitude\\", json_extract_scalar(vcattribs, ''$.partnerName'') AS \\"Partner Name\\", json_extract_scalar(vcattribs, ''$.businessName'') AS \\"Business Name\\", json_extract_scalar(vcattribs, ''$.merchantType'') AS \\"Merchant Type\\", vcregisteredmobile AS \\"Mobile Number\\", json_extract_scalar(vcattribs, ''$.turnoverType'') AS \\"Turn Over Type\\", json_extract_scalar(vcattribs, ''$.ownershipType'') AS \\"Ownership Type\\", json_extract_scalar(vcattribs, ''$.acceptanceType'') AS \\"Acceptance Type\\", json_extract_scalar(vcattribs, ''$.sellerVerifiedAccountName'') AS \\"Verified Account Name\\", json_extract_scalar(vcattribs, ''$.settlementAccountNo'') AS  \\"Settlement Account No\\", json_extract_scalar(vcattribs, ''$.settlementIfscCode'') AS \\"Settlement IFSC Code\\", json_extract_scalar(vcattribs, ''$.oclOnboardingDate'') AS  \\"OCL Onboarding Date\\",  irecordstatus AS \\"Record Status\\" FROM t17refined.masters.customers WHERE itenantid = :tenantid :AttribsForm AND dtentrydatetime BETWEEN CAST(:StartDate AS TIMESTAMP(6)) AND CAST(:EndDate AS TIMESTAMP(6)) ORDER BY icustomerid DESC LIMIT :Load "
    }
}'::text WHERE
idashboardqueryid = 164 AND itenantid = 17;